package com.booksyde.controller;import com.booksyde.service.FileStorageService;import java.util.Map;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;@RestController @RequestMapping("/api/v1/files")public class FileController{private final FileStorageService storage;public FileController(FileStorageService s){storage=s;}@PostMapping(value="/upload",consumes="multipart/form-data")@PreAuthorize("@authorizationService.hasRole(authentication, 'ADMIN') or @authorizationService.hasRole(authentication, 'PUBLISHER') or @authorizationService.hasRole(authentication, 'CREATOR')")public Map<String,String> upload(@RequestParam String bucket,@RequestParam String path,@RequestPart MultipartFile file){if(!java.util.Set.of("mangas","contracts","covers","books").contains(bucket))throw new IllegalArgumentException("Bucket não permitido.");return Map.of("path",storage.upload(bucket,path,file));}}
